})""","""// The signed-in user's notes as a download: JSON (`format` json, the default) or CSV (`format` csv).
export const exportNotes = endpoint({
  method: 'GET',
  path: '/api/export',
  input: z.object({ format: z.string().default('json') }),
  output: 'response',
  errors: { Unauthorized: z.object({ message: z.string() }), BadFormat: z.object({ message: z.string() }) },
  failed: { Unauthorized: 401, BadFormat: 400 },
})""")
open(p,'w').write(s)
p='features/notes/server.ts'; s=open(p).read()
s=s.replace("""    implement(exportNotes, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', { message: 'Sign in' })
      const own = listOf(session)
      return {
        user: session.user,
        notes: [...own.filter((item) => item.pinned), ...own.filter((item) => !item.pinned)].map((item) => ({
          title: item.title,
          pinned: item.pinned,
          archived: item.archived,
          createdAt: new Date(item.createdAt).toISOString(),
        })),
      }
    }),""","""    implement(exportNotes, ({ format }, { session, fail }) => {
      if (!session) return fail('Unauthorized', { message: 'Sign in' })
      if (format !== 'json' && format !== 'csv') return fail('BadFormat', { message: 'Use format json or csv' })
      const own = listOf(session)
      const notes = [...own.filter((item) => item.pinned), ...own.filter((item) => !item.pinned)].map((item) => ({
        number: item.number,
        title: item.title,
        body: (item.body ?? '').replace(/\\r\\n?/g, '\\n'),
        pinned: item.pinned,
        archived: item.archived,
        createdAt: new Date(item.createdAt).toISOString(),
      }))
      const download = (body: string, type: string) =>
        new Response(body, {
          status: 200,
          headers: { 'content-type': type, 'content-disposition': `attachment; filename="notes-${session.user}.${format}"` },
        })
      if (format === 'json') return download(JSON.stringify({ user: session.user, notes }), 'application/json; charset=utf-8')
      const cell = (value: string | number | boolean) => {
        const raw = String(value)
        return /[",\\r\\n]/.test(raw) ? `"${raw.replace(/"/g, '""')}"` : raw
      }
      const lines = [
        'number,title,body,pinned,archived,createdAt',
        ...notes.map((note) => [note.number, note.title, note.body, note.pinned, note.archived, note.createdAt].map(cell).join(',')),
      ]
      return download(lines.map((line) => `${line}\\r\\n`).join(''), 'text/csv; charset=utf-8')
    }),""")
open(p,'w').write(s)
p='features/notes/views.ts'; s=open(p).read()
s=s.replace("""        ui.a({ href: ui.link(exportNotes, {}), class: 'underline' }, [text.export]),""","""        ui.a({ href: ui.link(exportNotes, {}), class: 'underline' }, [text.export]),
        ui.a({ href: ui.link(exportNotes, { format: 'csv' }), class: 'underline' }, [text.exportCsv]),""")
open(p,'w').write(s)
p='features/notes/text.ts'; s=open(p).read()
s=s.replace("    export: 'Export',\n","    export: 'Export',\n    exportCsv: 'Export CSV',\n")
open(p,'w').write(s)
EOF
